import pathlib,hashlib,re
exec(pathlib.Path(__file__).with_name('common.py').read_text(encoding='utf8'))
reviews=load('docs/editorial/news-reviews.json');news=[]
def article(key,slug,title,en,desc,de,pairs,sources,review):
 paras=[(None,None,z,e) for z,e in pairs]
 paras += [('資料與報導方法','Sources and reporting method',review['method'],review['methodEn'])]
 a=write(key,slug,title,en,desc,de,paras,sources,extra=dict(country=t({'us':'美國','uk':'英國','jp':'日本'}[key],{'us':'United States','uk':'United Kingdom','jp':'Japan'}[key])))
 raw=(R/a['publishedPath']).read_text(encoding='utf8').split('---',2)[2]
 review.pop('method');review.pop('methodEn');review.update(primarySource=sources[0][1],independentSource=sources[1][1],reviewedAt=D,bodySha256=hashlib.sha256(raw.encode()).hexdigest())
 reviews[slug]=review;news.append(a)

article('us','us-penn-state-tuition-lawsuit-november-2026','美司法部控賓州州立學費政策：居住資格之爭，尚非國際生費率變更','US challenges Penn State tuition policy: a residency dispute, not a new international fee schedule','聯邦政府挑戰無合法移民身分居民的州內學費待遇；校方回應仍在審閱，訴訟主張不能當成法院判決。','The federal challenge concerns resident tuition for undocumented students. Penn State is reviewing the complaint; allegations are not a court ruling.',[
('美國司法部11月5日宣布對賓州州立大學提出民事訴訟，挑戰學校向部分無合法移民身分的賓州居民提供州內學費的政策。對正做赴美預算的台灣家庭，這是值得追蹤的公立大學收費爭議，但截至本次查核，所取得的是政府起訴與校方初步回應，不是命令所有國際學生改繳另一種費率的法院裁判。','The US Department of Justice announced a civil lawsuit against Pennsylvania State University on November 5, challenging resident tuition for some undocumented Pennsylvania residents. Taiwanese families planning US study should follow the dispute, but the material reviewed consists of a complaint and an initial university response. It is not a ruling requiring all international students to pay a different tuition rate.'),
('這場爭議的起點，是州內、州外與國際學費身分並非同一條分類線。居住地、在地就學經歷及移民身分可以同時出現在資格規則裡；新聞中「移民學生」一詞，卻容易把這些不同條件混為一談。若直接把涉及無合法身分居民的政策套用到持學生簽證赴美的人，就會在尚未閱讀收費辦法之前，先得到錯誤的預算結論。','The starting point is that residence, out-of-state status and international fee classification are not interchangeable categories. Residence, local schooling and immigration status can all appear in eligibility rules. The broad label “immigrant students” can obscure those differences. Applying a policy for undocumented residents directly to someone travelling on a student visa would produce a budget conclusion before the actual fee rules had been examined.'),
('司法部的論點是，賓州州立讓特定非公民享有依居住資格而來的優惠，卻未將相同待遇提供給州外美國公民，因此違反聯邦法；政府要求禁止校方繼續執行被挑戰的安排。這是原告提出的法律解釋與救濟請求，是否成立仍須看法院如何處理。起訴文件的重要性在於界定爭點，而不是預先替法官宣布結果。','DOJ argues that Penn State grants a residence-based benefit to certain noncitizens without extending equivalent treatment to US citizens living elsewhere, contrary to federal law. It seeks to stop the challenged policy. This is the plaintiff’s legal interpretation and requested remedy; its success depends on judicial proceedings. A complaint defines a dispute rather than deciding it.'),
('美聯社記者Heather Hollingsworth另向校方取得回應：賓州州立表示正在審閱訴狀。這個有限回應沒有確認司法部的指控，也沒有公布新的學生帳單或實施日期。本次閱讀的報導沒有提供校方完整法律答辯，因此不能把「仍在審閱」寫成認錯、接受變更，或已經決定終止優惠。後續正式答辯才可能交代校方如何解釋現行制度。','In separate reporting, AP’s Heather Hollingsworth obtained Penn State’s response that it was reviewing the complaint. That limited statement neither accepts DOJ’s allegations nor announces new bills or an implementation date. The report reviewed does not contain the university’s full legal defence. Reviewing a complaint should therefore not be presented as admitting fault, agreeing to changes or deciding to terminate a benefit.'),
('美聯社也交代這類制度支持者的不同理解：若美國公民滿足相同的居住或高中就學條件，也可得到相同待遇，優惠未必是單憑國籍作區分。這讓爭論回到「誰與誰在同樣條件下比較」，而不只是哪一群學生繳得比較少。兩種說法涉及的比較對象不同；新聞報導能呈現爭點，卻不能用一句公平或不公平替代法律審理。','AP also explains supporters’ reasoning: citizens who meet the same residence or high-school conditions can receive the same treatment, so nationality alone may not determine the benefit. The dispute therefore concerns which people should be compared under which conditions, not simply which group pays less. These arguments use different comparators. Reporting can explain that disagreement without substituting an editorial fairness judgment for legal adjudication.'),
('此次行動也不是孤立校務事件。司法部把它放在針對州內學費優惠的一系列訴訟中；美聯社的報導則說明，其他地方已因相關壓力改變政策。這提供了理解聯邦執法方向的背景，但其他州或其他學校的處理結果，不能自動套到賓州州立。各案規則、訴訟程序與可能命令的適用範圍，仍要逐一比較。','The case is part of a wider federal campaign against resident-tuition benefits. DOJ places it within a series of lawsuits, while AP describes policy changes elsewhere under related pressure. That helps explain the enforcement context, but outcomes in another state or institution do not automatically determine Penn State’s position. The policy wording, procedural stage and scope of any order must be compared separately.'),
('對台灣申請者而言，目前最實際的影響是辨識資訊層級。家庭可把校方核定的學費身分、所申請課程的年度費用與個人獎助通知放在同一份預算表，再觀察訴訟是否真的促成校方公告。新聞標題談到州內優惠，不等於外國學生取得優惠；同樣地，政府要求撤銷某種優惠，也不等於所有學生已收到追繳通知。','For Taiwanese applicants, the immediate task is to distinguish levels of evidence. A budget can bring together the university’s assigned fee status, the relevant programme’s annual charges and the applicant’s award notice, then be revised if litigation produces an actual university announcement. A headline about resident tuition does not establish eligibility for a foreign student, and a request to withdraw a benefit does not mean every student has received a retrospective bill.'),
('已在美國就讀、具有較複雜家庭或居留背景的學生，則需要向學校負責學費分類的單位確認個案，而不是在社群上公開證件來尋求答案。這是編輯依爭議範圍提出的資訊處理建議，不是對任何人的法律身分判斷。可核對的文件應說明適用學期、分類依據與申復方式；只有口頭傳聞，無法支持是否應改變繳費安排的決定。','Students already in the US with more complex family or residence circumstances need an individual explanation from the university office responsible for fee classification, rather than posting identity documents on social media. This is an editorial information-handling recommendation, not a determination of anyone’s legal status. Useful documentation identifies the term, basis of classification and review process; rumour alone cannot establish whether payment arrangements should change.'),
('這宗案件接下來值得追蹤的，是法院是否發布具體命令、校方是否提出正式答辯，以及收費單位是否向受影響學生發出書面通知。三者分別對應法律程序、當事方立場與實際執行，不能互相代替。本文未取得足以量化受影響台灣學生人數的資料，也不推估勝訴機率；現階段能確定的是爭議已進入訴訟，而不是新的統一學費規則已經生效。','The next meaningful developments are a specific court order, a formal university response and written implementation notices to affected students. These represent procedure, a party’s position and actual administration, respectively; none substitutes for the others. The material reviewed cannot quantify affected Taiwanese students or predict the litigation outcome. What is established is that a policy dispute has entered litigation, not that a new universal tuition rule has taken effect.')],[
('US Department of Justice — November 5 complaint announcement','https://www.justice.gov/opa/pr/department-justice-files-complaint-against-pennsylvania-state-university-challenging-its'),
('Associated Press — Heather Hollingsworth report and Penn State response','https://apnews.com/article/penn-state-trump-instate-tuition-164d7d9e4e760e8207b6c97c54c8fea9')],dict(newsValue='11月5日起訴引發公立大學學費分類爭議，區分訴訟主張與已生效收費，避免台灣家庭誤讀。',background='說明居住、高中就學、國籍與國際學生費率不是同一分類，交代州內優惠的制度爭點。',development='依司法部起訴公告及AP取得的校方回應重建程序階段，沒有將其他州結果套到此案。',perspectives='呈現司法部的聯邦法論點、AP報導的制度支持者比較基準，以及校方仍審閱的有限回應。',taiwanImpact='依申請者與既有學生的不同處境，連結費率分類、學校書面通知及預算修訂所需證據。',uncertainty='未取得裁判或完整答辯，不估勝訴與台灣受影響人數，不把政府請求寫成已實施命令。',independence='司法部是原告第一手公告，AP由署名記者另取得校方回應並加入制度支持者與跨州背景。',method='本文實讀司法部11月5日公告及美聯社完整報導；AP頁面顯示台北時間11月6日更新。司法部為訴訟一方，AP提供獨立報導與校方回應。本刊未採訪當事人，法律結論保留給法院。照片為賓州州立Old Main資料照。',methodEn='We read DOJ’s November 5 announcement and the full AP report, displayed as updated November 6 in Taipei. DOJ is a litigant; AP provides separate reporting and a university response. We did not interview the parties and do not decide the legal merits. The photograph is an archive view of Penn State’s Old Main.'))

article('uk','uk-hepi-ofs-ukvi-regulatory-coherence-2026','同一所大學，兩套完成率：HEPI追問英國國際學生監管如何銜接','One university, two completion measures: HEPI questions UK regulatory coordination','11月5日政策報告指出教育品質與簽證合規指標的落差；台灣學生選校，還需追問中斷學業時的保障。','A November 5 policy paper examines the gap between educational outcomes and visa compliance, raising questions about protection when study is disrupted.',[
('英國高等教育政策研究所HEPI於11月5日發布政策報告，把國際招生的一項難題拉到檯面：同一所英格蘭大學可能同時面對教育品質與學生簽證監管，兩者都使用「完成」等字眼，卻不一定衡量同一批學生或同一種結果。對台灣留學家庭，這場討論的重要性不只是行政負擔，而是學校的合規決策如何影響入學與完成學業的機會。','HEPI published a policy paper on November 5 examining a problem in international recruitment: an English institution can face both educational-quality and student-visa regulation, with similar terms such as “completion” measuring different populations or outcomes. For Taiwanese families, the issue extends beyond administrative workload to how compliance decisions can affect admission and the opportunity to finish a course.'),
('報告由Birmingham City University International College院長Olufunke Aluko-Daniels撰寫。她的核心主張不是取消監管，而是要求Office for Students與UK Visas and Immigration在交界處更一致。前者關注高等教育成果，後者關注被擔保來英的學生是否依其身分完成課程；學校同時承擔兩者責任，不能用通過其中一套檢查來證明另一套也沒有問題。','The author, Olufunke Aluko-Daniels, is principal of Birmingham City University International College. Her argument is for better coordination between the Office for Students and UK Visas and Immigration, rather than the removal of regulation. One concerns educational outcomes; the other examines whether sponsored students follow through on their courses. An institution’s compliance with one framework does not prove compliance with the other.'),
('數字最容易使這個問題被簡化。報告比較OfS全時學士完成率75%的門檻與UKVI不同時點的要求，但讀者不能把兩個百分比當作同一份成績單。母體、觀察期間、完成的定義以及未達門檻後的處理，都會改變指標意義。單看哪一個數字高，既無法排出學校教學品質，也無法判斷某個學生的學業表現是否合格。','Numbers can oversimplify this problem. The paper compares an OfS threshold of 75% for full-time undergraduate completion with UKVI requirements at different dates. They are not scores on a single scale. Population, observation period, the meaning of completion and consequences below a threshold all affect interpretation. The higher percentage alone cannot rank teaching quality or determine whether an individual student is performing satisfactorily.'),
('一個已發生的案例提供了具體背景。英國內政部8月6日公告，Bloomsbury Institute因未通過年度基本合規評估，在前一日被撤銷學生擔保資格。公告特別說明，該次評估採6月1日加嚴之前的標準：拒簽率低於10%、註冊率至少90%、完成率至少85%。因此不能把這組舊評估門檻寫成11月仍適用於所有新評估的統一規則。','A documented case provides context. On August 6, the Home Office announced that Bloomsbury Institute’s sponsor licence had been revoked the previous day after a failed Basic Compliance Assessment. It explicitly said that assessment used standards preceding June 1: refusal below 10%, enrolment at least 90% and completion at least 85%. Those historical thresholds should not be presented as the universal rules for new assessments in November.'),
('內政部在同一公告中表示，現有受擔保學生不會立即全部受影響，校方可在短期間繼續教學；少部分無法於安排期限內完成課程者，需要獲協助轉校，或處理其他合格居留途徑。這顯示行政處分與學生後續安排有不同時間線。撤照不是校內每一個人的學籍瞬間消失，但可繼續授課一段時間，也不等於所有人原訂的畢業路徑都受到完整保障。','The same announcement said existing sponsored students would not all be affected immediately and teaching could continue briefly. A smaller group unable to finish within that window would need help transferring or consider another eligible immigration route. The decision and its student arrangements therefore follow different timelines. Revocation does not instantly erase every enrolment, but a temporary teaching period does not guarantee every original path to graduation.'),
('HEPI把這種銜接問題延伸到休學、轉學與中途取得其他資格的情況。教育上可以理解的學習變動，在不同監管統計裡未必得到相同分類；學校若只以降低合規風險為目標，可能影響招生選擇與支持方式。這是報告對制度誘因的分析，尚不能證明每一所學校都排除相同學生，更不能據此宣稱台灣申請者已受到某種一致的新限制。','HEPI extends the coordination question to interruptions, transfers and intermediate qualifications. A change that makes educational sense may be classified differently across regulatory measures. A school focused on reducing compliance risk may alter recruitment or support decisions. That is an analysis of institutional incentives, not proof that every institution excludes the same applicants or that Taiwanese candidates face a uniform new restriction.'),
('大學端對行政成本的疑慮也有較早背景。Universities UK委託Moorhouse的研究估計，受訪大學平均有17.6個全時當量人力專門處理合規，但報告明示資料主要來自會員自陳的經驗與感受，不代表OfS認定學校必須投入這麼多人。這項限制很關鍵：成本數字可以支持進一步檢查重複作業，不能單獨證明所有監管都無效或應撤除。','Earlier evidence also documents universities’ concern about administrative cost. Research commissioned by Universities UK from Moorhouse estimated an average of 17.6 full-time-equivalent staff dedicated to compliance. It explicitly relied mainly on members’ reported experience and perceptions, not a determination of what OfS requires. The figure supports examining duplication, but does not establish that all regulation is ineffective or should be removed.'),
('對正在比較英國學校的台灣學生，本文的編輯分析是：除了課程內容與學費，應把「如果學習中斷，誰負責協助」納入選校問題。學校是否說明轉學後學分、已繳費用、住宿與學習支持如何處理，往往比一個未交代分母的完成率更有用。這些問題不表示某校即將出事，而是把招生承諾延伸到整個學習過程，讓家庭看見實際的責任分工。','Our editorial assessment is that Taiwanese applicants should ask who would help if study were disrupted, alongside comparing courses and fees. Explanations about transferred credit, paid fees, housing and academic support can be more useful than a completion figure without a denominator. Asking does not imply a school is about to lose its licence; it extends scrutiny of recruitment promises to responsibility throughout the student journey.'),
('報告提出的方向包括釐清定義、評估規則累積影響，以及建立監管機關之間較正式的協調。這些仍是政策建議，並不是已生效的新學生權利或簽證寬免。本次沒有取得政府接受全部建議的證據；後續應追蹤正式指引是否改變、學生保護安排是否更明確，以及新的制度是否真的減少中斷。只有觀察實施結果，才能評估協調改善了什麼。','Recommendations include clearer definitions, assessment of cumulative effects and more formal regulatory coordination. These remain policy proposals, not new student entitlements or immigration exemptions. We found no evidence that government had adopted the whole package. The next questions are whether formal guidance changes, protection arrangements become clearer and actual disruption falls. Outcomes, rather than the existence of a report, will show what coordination achieves.')],[
('Home Office — Bloomsbury sponsor revocation and student arrangements, August 6','https://www.gov.uk/government/news/bloomsbury-institutes-student-sponsor-licence-revoked'),
('HEPI — One sector, two regulators, November 5','https://www.hepi.ac.uk/reports/one-sector-two-regulators-the-office-for-students-uk-visas-and-immigration-and-the-challenge-of-regulatory-coherence-in-international-education/'),
('HEPI Policy Note 77 — full analysis','https://www.hepi.ac.uk/wp-content/uploads/2026/11/HEPI-Policy-Note-77.pdf'),
('Universities UK — Addressing the challenge of regulatory burden','https://www.universitiesuk.ac.uk/sites/default/files/uploads/Reports/UUK-briefing-Addressing-the-challenge-of-regulatory-burden%20.pdf')],dict(newsValue='11月5日新報告把國際學生監管與學習連續性相連，說明完成率與簽證資格不能互相代替。',background='區分OfS教育成果與UKVI擔保目的，並用8月Bloomsbury個案說明處分與學生安排不同。',development='明確區別舊評估門檻、6月制度變動與11月政策建議，不把建議冒充已生效規定。',perspectives='內政部執法理由、HEPI學者制度分析與UUK委託研究並列，交代產業自陳資料的限制。',taiwanImpact='提出轉學學分、費用、住宿與學習支持的責任問題，連結選校資料與整段學習風險。',uncertainty='不推論台灣生遭一致限制，不宣稱政府採納建議，數字母體不同且行政成本不是因果證明。',independence='Home Office為實際處分的第一手來源；HEPI為外部分析者，非轉載政府公告，UUK另有委託調查。',method='實讀內政部公告、HEPI發布頁及政策報告，另讀UUK研究及限制說明。HEPI作者為國際學院院長，其觀點有明確專業與制度位置；UUK代表大學端，兩者都不是政府規則本身。本刊未另行採訪。照片為Birmingham City University資料照，不是Bloomsbury。',methodEn='We read the Home Office notice, HEPI release and policy paper, plus UUK research and its limitations. HEPI’s author leads an international college; UUK represents universities. Their positions are identified and neither is treated as government regulation. We conducted no additional interviews. The archive photograph shows Birmingham City University, not Bloomsbury.'))

article('jp','japan-womens-universities-coeducation-transition-2026','日本女子大學轉向共學：改名之外，留學生要看懂學部與學位的轉接','Japan’s women’s universities turn coeducational: what changes beyond the name','追蹤平安女學院十月構想與金城學院七月決定，區分共學、更名、設置者變更及仍待核准的環節。','A follow-up on Heian Jogakuin’s October plan and Kinjo Gakuin’s July decision distinguishes coeducation, renaming, institutional transfer and pending approval.',[
('日本女子大學的改制，正在使選校問題超出「明年能否招收男生」的範圍。平安女學院10月5日提出2028年度共學與更名構想，同時規劃將兒童教育學部轉由另一所大學設置。本文在11月7日重新對照公告與外部報導，追蹤這些改變對未來入學者的意義；它是既有決策的分析，不是把十月消息重新包裝成今天才發生的事件。','Changes at Japan’s women’s universities raise questions beyond whether men can enrol next year. Heian Jogakuin announced plans on October 5 for coeducation and a new name from 2028, alongside a proposed transfer of its child-education faculty to another university. This November 7 follow-up compares the announcement with outside reporting and examines implications for future entrants. It does not present October’s decision as breaking news.'),
('依平安女學院公告，京都校區預計以國際觀光學部為單一學部，採用構想中的京都地域共創大學名稱；高槻校區的兒童教育學部則規劃於2028年4月改由環太平洋大學設置，相關認可尚須申請。這不是整所學校單純換一面招牌。不同學部的管理主體與發展路徑分開，申請者必須先確認自己想讀哪個課程，再看其所屬的改制安排。','Heian Jogakuin’s announcement envisages a Kyoto campus focused on international tourism under the proposed name Kyoto Chiiki Kyoso University. The child-education faculty at Takatsuki is planned to move to International Pacific University in April 2028, subject to an approval application. This is more than replacing a sign. Different faculties would follow different institutional paths, so applicants need to identify their intended programme before interpreting the transition.'),
('公告亦保留了幾個容易被忽略的界線：學校法人平安女學院的名稱不變，中學與高中繼續女子教育，附屬幼兒園仍由原法人運作。換言之，大學共學不等於整個教育體系全面共學；特定學部設置者變更，也不能推論所有校區都搬遷。把法人、學校、學部與校區分開閱讀，是避免把招生宣傳中的簡稱理解過度的第一步。','The notice preserves several boundaries: the school corporation keeps its name, its junior and senior high schools continue educating girls, and the kindergarten remains under the existing corporation. University coeducation therefore does not mean the entire school system becomes mixed, and transferring one faculty does not establish that every campus will move. Distinguishing corporation, university, faculty and campus prevents shorthand recruitment language from being overinterpreted.'),
('首爾經濟日報10月9日的署名報導，援引日本媒體與學者說明招生壓力：平安女學院在校人數由2022年度627人降至今年354人。這是同一機構兩個時點的規模比較，不是所有日本女子大學的平均，更不是外國學生錄取率。報導另引述專家觀點，指出少子化之外，女性升學與職業選擇改變，也會影響傳統女子大學的課程吸引力。','An October 9 Seoul Economic Daily report, drawing on Japanese reporting and expert commentary, describes enrolment pressure: Heian Jogakuin’s student population fell from 627 in 2022 to 354 this year. These are two observations for one institution, not a national average or an international admission rate. The report also presents the view that changing educational and career choices among women matter alongside demographic decline.'),
('這讓「少子化所以改共學」的直線解釋顯得不足。放寬招生對象可能擴大潛在申請池，但學生是否願意來，仍取決於課程、地點、成本及畢業後的選擇。編輯分析認為，改制應被當作一組待觀察的教育與經營決策；若只看性別門檻移除，就可能忽略校方是否同時改變學部定位，以及新的學習內容究竟何時公布。','That makes a simple demographic explanation incomplete. Widening eligibility may enlarge the potential applicant pool, but demand still depends on programmes, location, cost and subsequent opportunities. Our editorial analysis treats restructuring as a set of educational and organisational decisions to be evaluated. Looking only at the removal of a gender restriction may obscure faculty changes and whether the proposed curriculum has actually been published.'),
('另一個可對照的案例是名古屋的金城學院大學。校方7月3日公告共學方向，並把2029年4月開始的安排與設置者移轉連結；中日新聞7月5日另報導董事會決策與校友組織意見蒐集。兩校的時間與程序並不相同，不能因為都出現「共學」就合併成同一批已完成改革。金城案例也提醒讀者，董事會決定、主管程序與學生正式入學之間可能相隔數年。','Kinjo Gakuin University in Nagoya offers a comparison. Its July 3 announcement links coeducation from April 2029 with a transfer of institutional responsibility. Chunichi Shimbun separately reported the board decision and alumni consultation on July 5. The two institutions have different timelines and procedures. The shared word “coeducation” does not make them one completed reform; years can separate a board decision, regulatory steps and the first affected intake.'),
('獨立報導的價值，也在於保留決策以外的聲音。中日新聞提到校友組織的調查程序，但本次取得資料沒有提供可用來代表全部校友的完整結果，因此本文不寫成校友一致支持或反對。首爾經濟日報英文版亦註明由韓文機器翻譯，轉述外語引語可能與原句不同；本文只歸屬其分析，不把翻譯句子加工成精確的日文訪談引語。','Independent reporting adds perspectives beyond an institutional decision. Chunichi describes an alumni survey process, but the material reviewed does not provide results that justify claiming unanimous support or opposition. Seoul Economic Daily also identifies its English version as AI-translated from Korean and cautions about translated quotations. We attribute its analysis without turning an English rendering into a purportedly exact Japanese interview quotation.'),
('台灣學生若計畫2027或2028年入學，可能在就讀期間跨越改制時點。比起猜測新校名是否影響履歷，更具體的核對項目是錄取通知上的學部、畢業證書授予機構、原有課程如何完成，以及轉接安排是否適用自己的入學年度。這些屬於應向校方取得書面說明的問題；本文沒有取得每個年級的完整過渡辦法，因此不保證現有學生必須轉校，也不保證任何條件都不變。','Taiwanese students entering in 2027 or 2028 could study across a transition date. More concrete questions than speculation about a new name on a résumé concern the faculty on an offer, the degree-awarding institution, completion of the original curriculum and which arrangements cover the intake year. These require written institutional answers. We did not obtain complete transition rules for every cohort and therefore guarantee neither compulsory transfer nor unchanged conditions.'),
('後續觀察應放在申請認可結果、正式募集要項與課程公布，而不是只追蹤改名新聞。平安女學院公告說明國際觀光學部內容將再公布，這本身就是目前資訊仍有限的證據。對留學生來說，共學可能增加選項，但無法單憑公告推算名額、獎助或就業結果。把尚待確認的環節留在選校表上，才能在新資訊出現時更新判斷，而不是讓宣傳標題替代一整段學習規劃。','The next evidence to watch is approval, formal admissions guidance and published curricula, rather than naming announcements alone. Heian Jogakuin says further details of tourism education will follow, itself showing that information remains incomplete. Coeducation may expand options, but an announcement cannot establish places, scholarships or employment outcomes. Recording unresolved questions allows a study plan to change when evidence arrives instead of letting a headline substitute for the plan.')],[
('Heian Jogakuin — October 5 restructuring announcement','https://www.heian.ac.jp/topics/20261005'),
('Chunichi Shimbun — Kinjo Gakuin decision and alumni context, July 5','https://edu.chunichi.co.jp/news/detail/12914/u00015'),
('Kinjo Gakuin — July 3 coeducation announcement','https://www.kinjo-u.ac.jp/ja/news/detail/?id=2864'),
('Seoul Economic Daily — women’s universities and enrolment, October 9','https://en.sedaily.com/international/2026/10/09/japans-womens-universities-turn-co-ed-as-enrollment-shrinks')],dict(newsValue='十月改制公告影響未來跨年度就學，追蹤分析重點為不同學部的學位與設置者轉接而非重發舊速報。',background='將少子化與課程選擇、女性職涯變化區分，不把共學單一措施寫成招生或經營成功保證。',development='對照平安2028構想與金城2029共學時間，明示申請認可與後續課程資訊尚未完成。',perspectives='官方決策與中日新聞校友脈絡、首爾經濟日報專家分析並列，未杜撰校友態度或直接訪談。',taiwanImpact='說明2027或2028入學者可能跨越轉接，應取得學部、學位授予機構與入學年度適用規則。',uncertainty='不把在校人數換成錄取率，未取得各年級過渡方案，不保證轉校或條件全不變，標示機器翻譯限制。',independence='兩所大學公告提供決策原文；中日新聞含董事會與校友調查報導，韓媒另做趨勢脈絡，非同稿轉載。',method='實讀兩校公告、中日新聞與首爾經濟日報。本文為11月7日追蹤分析，保留7月及10月事件日期；未進行新訪談。韓媒英文版的機器翻譯限制已揭露，未採用逐字外語引語。照片為金城學院資料照，不是平安女學院。',methodEn='We read both institutional announcements, Chunichi Shimbun and Seoul Economic Daily. This is a November 7 follow-up retaining July and October event dates, with no new interviews. The Korean outlet’s machine-translation limitation is disclosed and no verbatim foreign-language quotations are used. The archive image shows Kinjo Gakuin, not Heian Jogakuin.'))
r['newsPrepared']=news
